#include <stdio.h>
#define MOD 998244353

int main() {
    int N, S;
    scanf("%d %d", &N, &S);
    int A[N];
    for (int i = 0; i < N; i++) {
        scanf("%d", &A[i]);
    }

    // dp[s] = number of subsequences (with increasing indices) that sum to s
    int dp[S + 1];
    for (int i = 0; i <= S; i++) dp[i] = 0;

    long long ans = 0;

    for (int i = 0; i < N; i++) {
        int val = A[i];
        // We need to update in reverse to avoid using current i multiple times
        for (int s = S; s >= 0; s--) {
            if (s + val <= S) {
                dp[s + val] = (dp[s + val] + dp[s]) % MOD;
            }
        }
        // Start a new subsequence at i
        if (val <= S) {
            dp[val] = (dp[val] + 1) % MOD;
        }
        // All subsequences ending at i with sum S contribute to all L <= i
        ans = (ans + dp[S]) % MOD;
    }

    printf("%lld\n", ans);
    return 0;
}

