#define MOD 998244353
#define MAXS 3001

long long C[MAXS], W[MAXS];
long long cnt_i[MAXS], wt_i[MAXS];

int main() {
    int N, S;
    scanf("%d %d", &N, &S);
    int A[N+1];
    for (int i = 1; i <= N; i++) scanf("%d", &A[i]);

    memset(C, 0, sizeof(C));
    memset(W, 0, sizeof(W));

    long long ans = 0;

    for (int i = 1; i <= N; i++) {
        memset(cnt_i, 0, sizeof(cnt_i));
        memset(wt_i, 0, sizeof(wt_i));

        if (A[i] <= S) {
            cnt_i[A[i]] = (cnt_i[A[i]] + 1) % MOD;
            wt_i[A[i]] = (wt_i[A[i]] + i) % MOD;
            for (int s = A[i]; s <= S; s++) {
                cnt_i[s] = (cnt_i[s] + C[s - A[i]]) % MOD;
                wt_i[s] = (wt_i[s] + W[s - A[i]]) % MOD;
            }
        }

        ans = (ans + wt_i[S] % MOD * ((N - i + 1) % MOD)) % MOD;

        for (int s = 0; s <= S; s++) {
            C[s] = (C[s] + cnt_i[s]) % MOD;
            W[s] = (W[s] + wt_i[s]) % MOD;
        }
    }

    printf("%lld\n", ans);
    return 0;
}

