#define MOD 998244353LL

typedef long long ll;

static ll mod_pow(ll a, ll e) {
    ll r = 1;
    while (e > 0) {
        if (e & 1) r = (r * a) % MOD;
        a = (a * a) % MOD;
        e >>= 1;
    }
    return r;
}

int main(void) {
    int N, S;
    if (scanf("%d %d", &N, &S) != 2) return 0;

    int *A = (int*)malloc((N + 1) * sizeof(int));
    for (int i = 1; i <= N; i++) scanf("%d", &A[i]);

    ll inv2 = mod_pow(2, MOD - 2);

    /* dp[t] = weighted count of subsequences with sum t
       after processing current prefix, where each chosen set
       contributes 2^{-(first_index)} in a transformed DP.
    */
    ll *dp = (ll*)calloc(S + 1, sizeof(ll));
    ll ans = 0;

    for (int i = 1; i <= N; i++) {
        int a = A[i];

        if (a <= S) {
            for (int t = S; t >= a; t--) {
                dp[t] += dp[t - a];
                if (dp[t] >= MOD) dp[t] -= MOD;
            }
            dp[a] += 1;   // start a new subsequence with first index = i
            if (dp[a] >= MOD) dp[a] -= MOD;
        }

        ans += dp[S];
        if (ans >= MOD) ans -= MOD;

        for (int t = 0; t <= S; t++) {
            dp[t] = (dp[t] * inv2) % MOD;
        }
    }

    free(A);
    free(dp);

    printf("%lld\n", ans % MOD);
    return 0;
}

import java.util.Scanner;

public class Main {
    static final int MOD = 998244353;

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int N = sc.nextInt();
        int S = sc.nextInt();
        int[] A = new int[N];
        for (int i = 0; i < N; i++) {
            A[i] = sc.nextInt();
        }

        int[] dp = new int[S + 1];
        dp[0] = 1; // empty subsequence

        long answer = 0;

        for (int i = 0; i < N; i++) {
            // update dp in reverse to avoid reuse within same subsequence
            for (int sum = S; sum >= A[i]; sum--) {
                dp[sum] = (dp[sum] + dp[sum - A[i]]) % MOD;
            }
            // number of subsequences ending at or before i with sum S
            answer = (answer + dp[S]) % MOD;
        }

        System.out.println(answer);
        sc.close();
    }
}

