        long[] dp = new long[S + 1];
        long ans = 0;

        for (int i = 1; i <= N; i++) {
            if (A[i] > S) continue;
            long contrib = (A[i] == S ? i : 0) + (S - A[i] >= 0 ? dp[S - A[i]] : 0);
            ans = (ans + contrib % MOD * ((N - i + 1) % MOD)) % MOD;
            for (int s = S - A[i]; s >= 0; s--) {
                dp[s + A[i]] = (dp[s + A[i]] + dp[s]) % MOD;
            }
            dp[A[i]] = (dp[A[i]] + i) % MOD;
        }

        System.out.println(ans);
    }
}

import java.io.*;
import java.util.*;

public class Main {
    static final long MOD = 998244353L;

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        int N = fs.nextInt();
        int S = fs.nextInt();

        long[] dp = new long[S + 1];
        long ans = 0;

        for (int i = 1; i <= N; i++) {
            int a = fs.nextInt();

            // Existing subsequences inside intervals ending before i
            // can be extended by A[i].
            if (a <= S) {
                for (int sum = S; sum >= a; sum--) {
                    dp[sum] += dp[sum - a];
                    if (dp[sum] >= MOD) dp[sum] -= MOD;
                }
                // Start a new subsequence consisting only of position i
                dp[a]++;
                if (dp[a] >= MOD) dp[a] -= MOD;
            }

            // For every possible L (1..i), empty choice is available.
            // This corresponds to multiplying all counts by 1 and adding
            // one new empty subsequence for each L, i.e. +i to dp[0].
            dp[0] += i;
            dp[0] %= MOD;

            // All subsequences summing to S among intervals ending at i
            ans += dp[S];
            ans %= MOD;
        }

        System.out.println(ans % MOD);
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }
}

#include <bits/stdc++.h>
using namespace std;
using int64 = long long;
const int MOD = 998244353;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, S;
    cin >> N >> S;
    vector<int> A(N);
    for (int i = 0; i < N; i++) cin >> A[i];

    int half = N / 2;

    // left half: indices 0..half-1
    vector<unordered_map<int, vector<pair<int,int>>>> left(half + 1);
    // left[count] = map from sum -> list of (first_index, last_index) relative to that half
    int left_n = half;
    for (int mask = 0; mask < (1 << left_n); mask++) {
        int sum = 0;
        int first = -1, last = -1;
        int cnt = 0;
        for (int i = 0; i < left_n; i++) {
            if (mask & (1 << i)) {
                sum += A[i];
                if (first == -1) first = i;
                last = i;
                cnt++;
            }
        }
        if (sum <= S) {
            left[cnt][sum].push_back({first, last});
        }
    }

    // right half: indices half..N-1
    int right_n = N - half;
    vector<unordered_map<int, vector<pair<int,int>>>> right(right_n + 1);
    for (int mask = 0; mask < (1 << right_n); mask++) {
        int sum = 0;
        int first = -1, last = -1;
        int cnt = 0;
        for (int i = 0; i < right_n; i++) {
            if (mask & (1 << i)) {
                sum += A[half + i];
                if (first == -1) first = half + i;
                last = half + i;
                cnt++;
            }
        }
        if (sum <= S) {
            right[cnt][sum].push_back({first, last});
        }
    }

    int64 ans = 0;

    // Combine: left part with sum s1, right part with sum S - s1
    for (int c1 = 0; c1 <= left_n; c1++) {
        for (auto &p1 : left[c1]) {
            int s1 = p1.first;
            int need = S - s1;
            if (need < 0) continue;
            for (int c2 = 0; c2 <= right_n; c2++) {
                auto it = right[c2].find(need);
                if (it == right[c2].end()) continue;
                // For each pair from left and right, combine
                for (auto &lv : p1.second) {
                    int L = lv.first;
                    // For empty left subsequence, we need special handling: L is not defined, treat as L=0
                    int64 leftL = (c1 == 0) ? 0 : L;
                    for (auto &rv : it->second) {
                        int R = rv.second;
                        int64 rightR = (c2 == 0) ? N - 1 : R;
                        int64 ways = (leftL + 1) * (N - rightR);
                        ans = (ans + ways) % MOD;
                    }
                }
            }
        }
    }

    // Also handle case where entire subsequence is only in left or only in right (already covered by meet-in-the-middle with empty other side)

    cout << ans % MOD << "\n";
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

const int MOD = 998244353;

int main(){
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int N, S;
    cin >> N >> S;

    vector<int> A(N+1);
    for(int i = 1; i <= N; i++) cin >> A[i];

    // dp[i][s] = sum of first_indices of subsequences ending at i with sum s
    // prefix[i][s] = sum_{j=1}^{i} dp[j][s]

    vector<vector<long long>> prefix(N+1, vector<long long>(S+1, 0));

    long long ans = 0;

    for(int i = 1; i <= N; i++){
        vector<long long> dp_i(S+1, 0);

        if(A[i] >= 1 && A[i] <= S){
            dp_i[A[i]] = (dp_i[A[i]] + i) % MOD;
        }

        // extend subsequences: dp_i[s] += prefix[i-1][s - A[i]]
        if(A[i] >= 1){
            for(int s = A[i]; s <= S; s++){
                dp_i[s] = (dp_i[s] + prefix[i-1][s - A[i]]) % MOD;
            }
        }

        // contribute to answer
        long long weight = (N - i + 1) % MOD;
        ans = (ans + dp_i[S] % MOD * weight) % MOD;

        // update prefix
        for(int s = 0; s <= S; s++){
            prefix[i][s] = (prefix[i-1][s] + dp_i[s]) % MOD;
        }
    }

    cout << ans << endl;

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

static const long long MOD = 998244353;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, S;
    cin >> N >> S;
    vector<int> A(N + 1);
    for (int i = 1; i <= N; ++i) cin >> A[i];

    // dp[t] = weighted count of subsequences ending in processed prefix
    // with sum t, where each subsequence contributes its number of valid L's.
    //
    // When processing position i:
    // - start new subsequence [i]: weight = i
    //   (for interval [L, R] containing this subsequence and ending at R>=i,
    //    L can be any 1..i)
    // - extend old subsequences by A[i], preserving weight
    //
    // After processing i, dp[S] is exactly the total contribution of all
    // subsequences with sum S and last chosen position <= i, counted by number
    // of possible L. Adding dp[S] over all i counts all possible R.
    vector<long long> dp(S + 1, 0);
    long long ans = 0;

    for (int i = 1; i <= N; ++i) {
        int a = A[i];
        if (a <= S) {
            for (int t = S; t >= a; --t) {
                dp[t] += dp[t - a];
                if (dp[t] >= MOD) dp[t] -= MOD;
            }
            dp[a] += i;
            if (dp[a] >= MOD) dp[a] -= MOD;
        }
        ans += dp[S];
        if (ans >= MOD) ans -= MOD;
    }

    cout << ans % MOD << '\n';
    return 0;
}
